"""A report generated by an older screenscribe gets the current agent panel when served.

Reports embed their scripts at generation time, so a fix to the agent panel
never reached a report made before it. ``refresh_live_assets`` swaps the panel
and i18n scripts for the installed version and appends the current panel CSS;
the on-disk file stays as generated.

Falsification: drop the ``refresh_live_assets`` call in the review server's
report route and ``test_served_old_report_carries_the_current_panel`` still
sees the old panel body.
"""

from __future__ import annotations

import json
from pathlib import Path

from fastapi.testclient import TestClient

from screenscribe.config import ScreenScribeConfig
from screenscribe.html_pro.assets import (
    load_css_agent_panel,
    load_js_agent_panel,
    load_js_i18n_runtime,
)
from screenscribe.review_server import create_review_app
from screenscribe.shell.renderer import refresh_live_assets

_OLD_PANEL = "// Floating Screenscribe agent chat for the HTML review report.\nvar OLD_PANEL = 1;"
_OLD_I18N = "// Shared i18n runtime for all screenscribe browser surfaces.\nvar OLD_I18N = 1;"


def _old_report() -> str:
    return (
        "<html><head><style>.old{}</style></head><body>"
        '<video id="videoPlayer" src="screen.mov"></video>'
        f"<script>\n{_OLD_I18N}\n</script>\n<script>\n{_OLD_PANEL}\n</script>"
        "</body></html>"
    )


def test_refresh_replaces_panel_and_i18n_and_appends_css() -> None:
    refreshed = refresh_live_assets(_old_report())
    assert "OLD_PANEL" not in refreshed
    assert "OLD_I18N" not in refreshed
    assert load_js_agent_panel() in refreshed
    assert load_js_i18n_runtime() in refreshed
    assert refreshed.index('<style id="ss-live-assets">') < refreshed.index("</head>")
    assert load_css_agent_panel() in refreshed


def test_refresh_leaves_unknown_or_ambiguous_documents_alone() -> None:
    plain = "<html><body><script>\nconsole.log(1)\n</script></body></html>"
    assert refresh_live_assets(plain) == plain
    twice = _old_report().replace("</body>", f"<script>\n{_OLD_PANEL}\n</script></body>")
    assert refresh_live_assets(twice).count("OLD_PANEL") == 2


def test_served_old_report_carries_the_current_panel(tmp_path: Path) -> None:
    output_dir = tmp_path / "review"
    output_dir.mkdir()
    report = output_dir / "screen_report.html"
    report.write_text(_old_report(), encoding="utf-8")
    (output_dir / "screen_report.json").write_text(json.dumps({"findings": []}), encoding="utf-8")
    video = output_dir / "screen.mov"
    video.write_bytes(b"\x00\x00\x00\x14ftypmp42")
    app = create_review_app(output_dir, report.name, video, ScreenScribeConfig())
    body = TestClient(app).get(f"/{report.name}").text
    assert "OLD_PANEL" not in body
    assert "function mdBlocks(" in body
    assert "OLD_PANEL" in report.read_text(encoding="utf-8")
